package fr.sary.radioprogrammee;
import android.app.*;import android.content.*;import java.util.*;import org.json.*;
public class Schedule {
 static android.content.SharedPreferences prefs(Context c){return c.getSharedPreferences("radio",0);}
 static JSONArray slots(Context c){try{return new JSONArray(prefs(c).getString("slots","[]"));}catch(Exception e){return new JSONArray();}}
 static void save(Context c,JSONArray a){prefs(c).edit().putString("slots",a.toString()).apply();refresh(c);}
 static boolean active(Context c,long time){Calendar cal=Calendar.getInstance();cal.setTimeInMillis(time);int day=(cal.get(Calendar.DAY_OF_WEEK)+5)%7;int minute=cal.get(Calendar.HOUR_OF_DAY)*60+cal.get(Calendar.MINUTE);JSONArray a=slots(c);for(int i=0;i<a.length();i++)try{JSONObject o=a.getJSONObject(i);int start=o.getInt("start"),end=o.getInt("end");int mask=o.getInt("days");if(start<end && (mask&(1<<day))!=0 && minute>=start&&minute<end)return true;if(start>end){if((mask&(1<<day))!=0&&minute>=start)return true;int prev=(day+6)%7;if((mask&(1<<prev))!=0&&minute<end)return true;}}catch(Exception ignored){}return false;}
 static void refresh(Context c){AlarmManager am=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);Intent intent=new Intent(c,AlarmReceiver.class);PendingIntent pi=PendingIntent.getBroadcast(c,0,intent,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);am.cancel(pi);long now=System.currentTimeMillis();boolean on=active(c,now);Intent service=new Intent(c,RadioService.class).setAction(on?"PLAY":"STOP");if(on)c.startForegroundService(service);else c.startService(service);
 long next=Long.MAX_VALUE;Calendar cal=Calendar.getInstance();JSONArray a=slots(c);for(int i=0;i<a.length();i++)try{JSONObject o=a.getJSONObject(i);int mask=o.getInt("days");for(int d=0;d<8;d++){Calendar x=(Calendar)cal.clone();x.add(Calendar.DAY_OF_YEAR,d);int day=(x.get(Calendar.DAY_OF_WEEK)+5)%7;if((mask&(1<<day))==0)continue;for(String k:new String[]{"start","end"}){int m=o.getInt(k);if(k.equals("end")&&o.getInt("start")>m)x.add(Calendar.DAY_OF_YEAR,1);x.set(Calendar.HOUR_OF_DAY,m/60);x.set(Calendar.MINUTE,m%60);x.set(Calendar.SECOND,0);x.set(Calendar.MILLISECOND,0);long t=x.getTimeInMillis();if(t>now+500&&t<next)next=t;if(k.equals("end")&&o.getInt("start")>m)x.add(Calendar.DAY_OF_YEAR,-1);}}}catch(Exception ignored){}if(next!=Long.MAX_VALUE){if(android.os.Build.VERSION.SDK_INT>=31&&!am.canScheduleExactAlarms())am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,next,pi);else am.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,next,pi);}}
}
